export const DATA = {"depts":[{"k":"PRD","en":"Production (L1 & L2)","ar":"الإنتاج (خط 1 وخط 2)"},{"k":"HYG","en":"Hygiene & Sanitation","ar":"النظافة والتطهير (الهايجين)"},{"k":"MNT","en":"Maintenance & Engineering","ar":"الصيانة والهندسة"},{"k":"QA","en":"Quality (QA/QC & Lab)","ar":"الجودة (QA/QC والمعمل)"},{"k":"WH","en":"Stores, Receiving & Shipping","ar":"المخازن والاستلام والشحن"},{"k":"ADM","en":"Admin, HR & Facilities","ar":"الشؤون الإدارية والموارد البشرية والمرافق"}],"areas":[{"k":"Z03","en":"Hygiene room, lockers & changing rooms (L1)","ar":"غرفة الهايجين والدواليب وغرف الملابس (خط 1)","z":"staff","s_ar":"الهايجين والدواليب","s_en":"Hygiene room"},{"k":"P","en":"Personnel hygiene & GMP (all staff in production & stores)","ar":"النظافة الشخصية وممارسات التصنيع الجيدة (كل العاملين بالإنتاج والمخازن)","z":"all","s_ar":"العاملون","s_en":"People"},{"k":"Z10","en":"L1 cooling, freezing & packing","ar":"خط 1 – التبريد والتجميد والتعبئة","z":"high","s_ar":"التجميد والتعبئة","s_en":"Freezing & packing"},{"k":"Z16","en":"QC lab & verification","ar":"معمل الجودة والتحقق","z":"restricted","s_ar":"معمل الجودة","s_en":"QC lab"},{"k":"Z14","en":"Cold stores & dispatch (docks 8–11)","ar":"الثلاجات والشحن (أبواب 8–11)","z":"high","s_ar":"الثلاجات والشحن","s_en":"Cold stores"},{"k":"Z13","en":"Dry stores (packaging, cartons, ingredients, oil, chemicals, spares)","ar":"المخازن الجافة (التغليف – الكرتون – المكونات – الزيت – الكيماويات – قطع الغيار)","z":"high","s_ar":"المخازن الجافة","s_en":"Dry stores"},{"k":"Z09","en":"L1 drying, batter & frying","ar":"خط 1 – التجفيف والبتر والقلي","z":"med","s_ar":"التجفيف والقلي","s_en":"Drying & frying"},{"k":"Z11","en":"Batter preparation (mixing) room","ar":"غرفة تحضير البتر (الخلط)","z":"restricted","s_ar":"غرفة البتر","s_en":"Batter room"},{"k":"Z08","en":"L1 cutting & blanching","ar":"خط 1 – التقطيع والسلق","z":"med","s_ar":"التقطيع والسلق","s_en":"Cutting & blanching"},{"k":"Z12","en":"Line 2 value-added hall (hash brown, noisettes, onion rings)","ar":"خط 2 – القيمة المضافة (هاش براون – نويزيت – حلقات البصل)","z":"allergen","s_ar":"خط 2","s_en":"Line 2"},{"k":"G","en":"Line controls – all production lines","ar":"ضوابط عامة – كل خطوط الإنتاج","z":"all","s_ar":"كل الخطوط","s_en":"All lines"},{"k":"Z07","en":"Peeling hall","ar":"صالة التقشير","z":"med","s_ar":"التقشير","s_en":"Peeling"},{"k":"Z06","en":"Raw potato receiving & storage (stores 1–6, feeding)","ar":"استلام وتخزين البطاطس الخام (العنابر 1–6 والتغذية)","z":"low","s_ar":"الخام والتغذية","s_en":"Raw & feeding"},{"k":"Z15","en":"Utilities, engineering & idle areas","ar":"المرافق والهندسة والمناطق غير المستخدمة","z":"ext","s_ar":"المرافق والهندسة","s_en":"Utilities"},{"k":"Z02","en":"Waste areas (garbage areas 1 & 2)","ar":"مناطق النفايات (1 و 2)","z":"ext","s_ar":"النفايات","s_en":"Waste"},{"k":"Z01","en":"Site exterior, gate & security","ar":"المناطق الخارجية والبوابة والأمن","z":"ext","s_ar":"الخارج والبوابة","s_en":"Outside & gate"},{"k":"Z05","en":"Cafeteria, kitchen, laundry, mosque & admin building","ar":"الكافتيريا والمطبخ والمغسلة والمسجد والمبنى الإداري","z":"staff","s_ar":"الكافتيريا والمرافق","s_en":"Cafeteria & staff"},{"k":"Z04","en":"Toilets (men, women, engineers, gate, admin)","ar":"دورات المياه (رجال – سيدات – مهندسين – البوابة – الإدارة)","z":"staff","s_ar":"دورات المياه","s_en":"Toilets"}],"points":[{"id":"Z03-01","a":"Z03","d":"HYG","f":"D","r":"F-C&S-16-02","b":"4.8","en":"Hand-wash basins clean; soap and sanitizer dispensers full","ar":"أحواض غسيل الأيدي نظيفة، وموزعات الصابون والمعقم ممتلئة","op":1,"h_ar":"أحواض غسيل الأيدي في غرفة الهايجين نظيفة، وموزعات الصابون والمعقم ممتلئة وتعمل. ✗ لو حوض متسخ أو موزع فارغ.","h_en":"Hand-wash basins in the hygiene room are clean; soap and sanitizer dispensers full and working. ✗ if a basin is dirty or a dispenser empty."},{"id":"Z03-02","a":"Z03","d":"MNT","f":"D","r":"F-C&S-16-02","b":"4.8","en":"Hands-free taps, warm water and hand dryers working","ar":"الصنابير بدون لمس والمياه الدافئة ومجففات الأيدي تعمل","h_ar":"جرب كل صنبور: يعمل بدون لمس، والمياه دافئة، ومجفف الأيدي يعمل. ✗ لو صنبور أو مجفف عطلان أو المياه باردة.","h_en":"Try every tap: hands-free, warm water, hand dryer working. ✗ if a tap or dryer is broken or the water is cold."},{"id":"Z03-03","a":"Z03","d":"HYG","f":"D","r":"F-C&S-16-02","b":"4.8","en":"Paper towels available; hand-washing steps poster posted","ar":"المناديل الورقية متوفرة، ولافتة خطوات غسيل الأيدي موجودة","op":1,"h_ar":"المناديل الورقية موجودة، ولافتة خطوات غسيل الأيدي واضحة. ✗ لو المناديل خلصت أو اللافتة غير موجودة.","h_en":"Paper towels available and the hand-washing poster clearly posted. ✗ if towels have run out or the poster is missing."},{"id":"Z03-05","a":"Z03","d":"HYG","f":"D","r":"L-L&B-10-04","b":"7.4","en":"Hairnets, beard nets, gloves, sleeves and blue plasters in stock","ar":"شبكات الشعر والذقن والقفازات والأكمام والبلاستر الأزرق متوفرة","op":1,"h_ar":"افتح دولاب المهمات: شبكات الشعر والذقن والقفازات والأكمام والبلاستر الأزرق متوفرة. ✗ لو صنف ناقص.","h_en":"Open the PPE cabinet: hairnets, beard nets, gloves, sleeves and blue plasters in stock. ✗ if any item has run out."},{"id":"Z03-06","a":"Z03","d":"HYG","f":"D","r":"F-C&S-16-02","b":"4.8","en":"Changing rooms (men & women): floors, benches and walls clean","ar":"غرف الملابس (رجال وسيدات): الأرضيات والمقاعد والحوائط نظيفة","op":1,"h_ar":"غرف الملابس رجال وسيدات: الأرضيات والمقاعد والحوائط نظيفة بدون أتربة أو بقع. ✗ لو متسخة.","h_en":"Men's and women's changing rooms: floors, benches and walls clean, no dust or stains. ✗ if dirty."},{"id":"Z03-07","a":"Z03","d":"HYG","f":"D","r":"F-L&B-04-01","b":"4.8","en":"No used hairnets, coats or gloves thrown on the floor","ar":"لا أغطية شعر أو بالطوهات أو قفازات ملقاة على الأرض","op":1,"h_ar":"انظر على الأرض في الهايجين وغرف الملابس: لا أغطية شعر أو بالطوهات أو قفازات ملقاة. ✗ لو وجدت.","h_en":"Look at the floor in the hygiene and changing rooms: no hairnets, coats or gloves thrown down. ✗ if found."},{"id":"Z03-08","a":"Z03","d":"ADM","f":"D","r":"F-L&B-05-01","b":"4.8","en":"Lockers: nothing on top; no food, drink or medicine inside (random check)","ar":"الدواليب: لا شيء أعلاها، ولا طعام أو شراب أو أدوية بداخلها (فحص عشوائي)","h_ar":"انظر أعلى الدواليب (لا شيء عليها)، وافتح 5 دواليب عشوائياً بحضور العامل أو المشرف: لا طعام أو شراب أو أدوية. ✗ لأي مخالفة.","h_en":"Nothing on top of the lockers; open 5 random lockers with the worker or supervisor present: no food, drink or medicine. ✗ for any breach."},{"id":"Z03-09","a":"Z03","d":"ADM","f":"D","r":"SOP-PRO-01","b":"4.8","en":"Work clothes kept separate from personal clothes; clean uniforms available","ar":"ملابس العمل منفصلة عن الملابس الشخصية، والزي النظيف متوفر","op":1,"h_ar":"الملابس الشخصية في مكان والزي في مكان آخر، والزي النظيف متوفر للوردية. ✗ لو مختلطة أو الزي النظيف غير كافٍ.","h_en":"Personal clothes in one place, uniforms in another; enough clean uniforms for the shift. ✗ if mixed or clean uniforms are short."},{"id":"Z03-10","a":"Z03","d":"MNT","f":"D","r":"SOP-L&B-12","b":"4.8","en":"Doors to production self-closing and kept closed","ar":"الأبواب المؤدية للإنتاج ذاتية الغلق ومغلقة","h_ar":"افتح الأبواب المؤدية للإنتاج واتركها: تغلق وحدها بالكامل. ✗ لو باب لا يغلق أو مثبت مفتوحاً.","h_en":"Open the doors to production and let go: they close fully by themselves. ✗ if a door does not close or is propped open."},{"id":"Z03-11","a":"Z03","d":"MNT","f":"D","r":"F-L&B-04-01","b":"4.8","en":"Lighting and ventilation working; no damp, mould or bad odour","ar":"الإضاءة والتهوية تعمل، ولا رطوبة أو عفن أو روائح","h_ar":"كل الإضاءة والشفاطات تعمل، ولا رطوبة أو عفن على الحوائط والسقف، ولا رائحة. ✗ لو عطل أو عفن.","h_en":"All lights and fans work, no damp or mould on walls and ceiling, no smell. ✗ if something is broken or mouldy."},{"id":"Z03-12","a":"Z03","d":"QA","f":"D","r":"SOP-PCP-01","b":"4.14","en":"Glue traps and insect light traps in place; no pest signs","ar":"مصائد الغراء وصواعق الحشرات في أماكنها، ولا علامات آفات","h_ar":"مصائد الغراء والصواعق في الهايجين وغرف الملابس موجودة وتعمل وغير ممتلئة. ✗ لو ناقصة أو عطلانة أو بها آفات كثيرة.","h_en":"Glue traps and insect killers in the hygiene and changing rooms are present, working and not full. ✗ if missing, broken or full of insects."},{"id":"P-01","a":"P","d":"PRD","f":"D","r":"F-PRO-01-05","b":"7.2","en":"Hands washed & sanitized at entry, after breaks, toilet and handling waste","ar":"غسل وتعقيم الأيدي عند الدخول وبعد الراحة ودورات المياه ولمس النفايات","op":1,"h_ar":"قف عند مدخل الإنتاج 5 دقائق وراقب 10 أشخاص على الأقل: غسيل بالصابون حوالي 20 ثانية ثم المعقم. ✗ لو شخص واحد دخل بدون غسيل.","h_en":"Stand at the production entrance for 5 minutes and watch at least 10 people: soap wash about 20 s, then sanitizer. ✗ if anyone enters without washing."},{"id":"P-02","a":"P","d":"PRD","f":"D","r":"I-PRO-04-01","b":"7.4","en":"Clean uniform in the correct colour for the area","ar":"زي نظيف باللون الصحيح للمنطقة","op":1,"h_ar":"راجع زي 10 عمال في مناطق مختلفة: نظيف وسليم، واللون حسب I-PRO-04-01 (الإنتاج نبيتي بمعطف أزرق، التعبئة نبيتي بمعطف رصاصي، الجودة رصاصي بمعطف أبيض، الصيانة زيتي). ✗ لو زي متسخ جداً أو ممزق أو لون خطأ.","h_en":"Check the uniform of 10 workers in different areas: clean, intact and the right colour (production maroon with blue coat, packing maroon with grey coat, QA grey with white coat, maintenance olive). ✗ if very dirty, torn or the wrong colour."},{"id":"P-03","a":"P","d":"PRD","f":"D","r":"SOP-PRO-01","b":"7.2","en":"Hair and ears fully covered by hairnet; beard / moustache net worn","ar":"الشعر والأذنين مغطاة بالكامل بشبكة الشعر وارتداء شبكة الذقن والشارب","op":1,"h_ar":"انظر للعمال على الخطوط: كل الشعر والأذنين داخل الشبكة، وشبكة ذقن لكل من له لحية أو شارب. ✗ لو ظهر شعر خارج الشبكة.","h_en":"Look at people on the lines: all hair and ears inside the hairnet, beard net on anyone with a beard or moustache. ✗ if hair shows outside the net."},{"id":"P-04","a":"P","d":"PRD","f":"D","r":"F-PRO-01-04","b":"7.2","en":"No jewellery, watches or piercings (only a plain wedding ring and glasses allowed)","ar":"لا مجوهرات أو ساعات أو حلقان (المسموح الدبلة السادة والنظارة فقط)","op":1,"h_ar":"افحص الأيدي والأذنين والرقبة لعينة من العمال: لا خواتم أو ساعات أو حلقان أو سلاسل. المسموح فقط الدبلة السادة والنظارة. ✗ لأي مجوهرات أخرى.","h_en":"Check hands, ears and neck of a sample of workers: no rings, watches, earrings or chains. Only a plain wedding ring and glasses are allowed. ✗ for any other jewellery."},{"id":"P-05","a":"P","d":"PRD","f":"D","r":"F-PRO-01-04","b":"7.2","en":"Nails short & clean; no nail polish, false nails / lashes or strong perfume","ar":"أظافر قصيرة ونظيفة، لا طلاء أو أظافر / رموش صناعية أو عطور نفاذة","op":1,"h_ar":"افحص أيدي 10 عمال: أظافر قصيرة ونظيفة، بدون طلاء أو أظافر أو رموش صناعية، ولا رائحة عطر قوية. ✗ لأي مخالفة.","h_en":"Check the hands of 10 workers: short clean nails, no polish, false nails or lashes, no strong perfume. ✗ for any breach."},{"id":"P-06","a":"P","d":"PRD","f":"D","r":"SOP-PRO-02","b":"7.4","en":"Gloves in production, sleeves at inspection & packing, aprons at peeling – clean and intact","ar":"قفازات في الإنتاج وأكمام في الفحص والتعبئة ومريلة في التقشير – نظيفة وسليمة","op":1,"h_ar":"تأكد أن عمال الإنتاج يلبسون قفازات، وعمال الفحص بعد الفراير والتعبئة يلبسون أكمام، وعمال التقشير يلبسون مريلة، وكلها نظيفة وسليمة. ✗ لو قفاز ممزق أو غير موجود.","h_en":"Production staff wear gloves, inspection-after-fryer and packing staff wear sleeves, peeling staff wear aprons – all clean and intact. ✗ if one is torn or missing."},{"id":"P-07","a":"P","d":"PRD","f":"D","r":"SOP-PRO-01","b":"7.2","en":"Cuts covered with blue detectable plaster + glove; first-aid kit has blue plasters","ar":"الجروح مغطاة بالبلاستر الأزرق القابل للكشف + قفاز، وصندوق الإسعافات به بلاستر أزرق","op":1,"h_ar":"اسأل عن أي جرح وافحصه: بلاستر أزرق قابل للكشف + قفاز. افتح صندوق الإسعافات وتأكد من وجود بلاستر أزرق. ✗ لو جرح مكشوف أو بلاستر عادي أو الصندوق بدونه.","h_en":"Ask about cuts and look: blue detectable plaster + glove. Open the first-aid box and check it has blue plasters. ✗ if a wound is uncovered, a normal plaster is used, or the box has none."},{"id":"P-08","a":"P","d":"PRD","f":"D","r":"F-A&HR-02-01","b":"7.3","en":"No one with illness symptoms (diarrhoea, vomiting, fever, skin infection) working with product","ar":"لا يعمل مع المنتج أي شخص به أعراض مرضية (إسهال – قيء – حرارة – عدوى جلدية)","c":1,"op":1,"h_ar":"اسأل مشرف كل قسم عن أي عامل مريض، ولاحظ أي عامل يبدو مريضاً (كحة شديدة – سخونية – قيء) أو به جرح ملتهب أو غير مغطى. ✗ (حرج) لو شخص به أعراض يعمل مع المنتج – يخرج فوراً ويبلغ مدير الجودة.","h_en":"Ask each section supervisor about sick workers and look for anyone who seems ill (heavy cough, fever, vomiting) or has an infected or uncovered wound. ✗ (critical) if a person with symptoms handles product – remove them and inform the QA Manager."},{"id":"P-09","a":"P","d":"PRD","f":"D","r":"SOP-PRO-01","b":"7.2","en":"No eating, drinking, gum, smoking or spitting in production; no food or drinks brought in","ar":"لا أكل أو شرب أو علكة أو تدخين أو بصق في الإنتاج، ولا إدخال طعام أو مشروبات","op":1,"h_ar":"امشِ في الصالات وانظر على الطاولات والرفوف والأرض: لا طعام أو أكواب أو علكة أو أعقاب سجائر. ✗ لأي دليل أكل أو شرب أو تدخين.","h_en":"Walk the halls and look on tables, shelves and floors: no food, cups, gum or cigarette ends. ✗ for any sign of eating, drinking or smoking."},{"id":"P-10","a":"P","d":"PRD","f":"D","r":"SOP-L&B-06","b":"4.9","en":"No mobile phones in production except authorised staff; no glass items","ar":"لا هواتف محمولة في الإنتاج إلا للمصرح لهم، ولا أدوات زجاجية","op":1,"h_ar":"لاحظ العمال: لا هواتف إلا مع المشرفين والمهندسين المصرح لهم، ولا أكواب أو زجاجات زجاج في الإنتاج. ✗ لو هاتف مع شخص غير مصرح أو زجاج.","h_en":"Watch the staff: phones only with authorised supervisors and engineers, no glass cups or bottles in production. ✗ if an unauthorised person has a phone or glass is found."},{"id":"P-11","a":"P","d":"PRD","f":"D","r":"SOP-PRO-01","b":"7.2","en":"Nothing in pockets above the waist; no pens behind ears; no staples, clips or pins","ar":"لا شيء في الجيوب أعلى الوسط، ولا أقلام خلف الأذن، ولا دبابيس أو مشابك","op":1,"h_ar":"افحص جيوب الصدر وخلف الأذن لعينة من العمال، وابحث عن دبابيس أو مشابك في الأوراق المعلقة بالصالة. ✗ لأي مخالفة.","h_en":"Check chest pockets and behind ears of a sample of workers, and look for staples or clips on papers posted in the hall. ✗ for any breach."},{"id":"P-12","a":"P","d":"PRD","f":"D","r":"SOP-PRO-01","b":"7.4","en":"White boots in production (black outside) and clean; visitors' shoes through the foot bath","ar":"حذاء أبيض داخل الإنتاج (أسود بالخارج) ونظيف، وأحذية الزوار تمر بحوض الأقدام","op":1,"h_ar":"كل من في الإنتاج يلبس حذاء أبيض نظيفاً، والأحذية السوداء لا تدخل، والزوار يمرون بحوض الأقدام. ✗ لو حذاء خارجي أو أسود داخل الإنتاج.","h_en":"Everyone in production wears clean white boots, black boots stay outside, visitors pass through the foot bath. ✗ if outdoor or black footwear is inside production."},{"id":"P-13","a":"P","d":"PRD","f":"D","r":"SOP-PRO-01","b":"7.4","en":"Work clothes not worn outside production (cafeteria, toilets, outside)","ar":"عدم ارتداء ملابس العمل خارج الإنتاج (الكافتيريا – دورات المياه – الخارج)","op":1,"h_ar":"امشِ في الكافتيريا ودورات المياه والساحة الخارجية: لا أحد بالبالطو أو زي الإنتاج. ✗ لو شخص بزي العمل خارج الإنتاج.","h_en":"Walk through the cafeteria, toilets and yard: nobody in a production coat or uniform. ✗ if someone wears work clothes outside production."},{"id":"P-14","a":"P","d":"PRD","f":"D","r":"SOP-L&B-12","b":"4.3","en":"Doors between zones closed after use; no unnecessary movement from low to high hygiene areas","ar":"غلق الأبواب بين المناطق بعد الاستخدام، وعدم التنقل غير الضروري من المناطق الأقل للأعلى نظافة","op":1,"h_ar":"انظر للأبواب بين الاستقبال والتقشير والتصنيع والتعبئة: مغلقة. لاحظ أن عمال المناطق الأقل نظافة لا يدخلون التعبئة بدون غسيل وتغيير. ✗ لو باب مفتوح بدون سبب أو انتقال غير مسموح.","h_en":"Doors between receiving, peeling, processing and packing are closed. Staff from lower-hygiene areas do not enter packing without washing and changing. ✗ if a door is open for no reason or someone crosses zones."},{"id":"Z10-01","a":"Z10","d":"HYG","f":"D","r":"F-C&S-01-02","b":"4.11","en":"Pre-cooler, freezer belts and freezer in/out clean – no product build-up","ar":"المبرد المبدئي وسيور الفريزر ومدخله ومخرجه نظيفة – لا تراكم منتج","op":1,"h_ar":"المبرد المبدئي وسيور الفريزر والمدخل والمخرج بدون منتج متراكم. ✗ لو بقايا.","h_en":"Pre-cooler, freezer belts, entrance and exit free of product build-up. ✗ if residue remains."},{"id":"Z10-02","a":"Z10","d":"HYG","f":"D","r":"F-C&S-01-02","b":"4.11","en":"Sizing vibrator, sorting belts, inspection tables, weighers and packing machines clean","ar":"هزاز التدريج وسيور الفرز وطاولات الفحص والموازين وماكينات التعبئة نظيفة","op":1,"h_ar":"هزاز التدريج وسيور الفرز وطاولات الفحص والموازين وماكينات التعبئة نظيفة. ✗ لو بقايا.","h_en":"Sizing vibrator, sorting belts, inspection tables, weighers and packing machines clean. ✗ if residue remains."},{"id":"Z10-03","a":"Z10","d":"HYG","f":"D","r":"F-LAB-17-02","b":"4.11","en":"Floor dry; no fries on the floor at freezer in/out or under belts","ar":"الأرضية جافة، ولا أصابع على الأرض عند مدخل/مخرج الفريزر أو أسفل السيور","op":1,"h_ar":"الأرض عند مدخل ومخرج الفريزر وأسفل السيور جافة ولا أصابع عليها. ✗ لو منتج على الأرض أو مياه.","h_en":"Floor at the freezer in/out and under belts dry, no fries on it. ✗ if product or water is on the floor."},{"id":"Z10-04","a":"Z10","d":"HYG","f":"D","r":"F-L&B-04-01","b":"4.11","en":"No standing water at the freezer basin, behind the freezer or under the hopper","ar":"لا مياه راكدة عند حوض الفريزر أو خلفه أو أسفل الهوبر","op":1,"h_ar":"عند حوض الفريزر وخلفه وأسفل الهوبر: لا مياه راكدة. ✗ لو بركة.","h_en":"At the freezer basin, behind the freezer and under the hopper: no standing water. ✗ if there is a puddle."},{"id":"Z10-05","a":"Z10","d":"HYG","f":"D","r":"F-L&B-04-01","b":"4.11","en":"Walls and door curtains between packing and processing clean","ar":"الحوائط وستائر الباب بين التعبئة والتصنيع نظيفة","h_ar":"الحوائط وستائر الباب بين التعبئة والتصنيع نظيفة. ✗ لو متسخة.","h_en":"Walls and door curtains between packing and processing are clean. ✗ if dirty."},{"id":"Z10-06","a":"Z10","d":"HYG","f":"D","r":"I-PRO-04-01","b":"4.11","en":"Blue tools and blue bins used in packing; cleaners in baby-green vests","ar":"استخدام الأدوات والسلات الزرقاء في التعبئة، وعمال النظافة بالسترات الخضراء الفاتحة","op":1,"h_ar":"أدوات وسلات التعبئة زرقاء، وعمال النظافة بالسترة الخضراء الفاتحة. ✗ لو لون آخر.","h_en":"Packing tools and bins are blue; cleaners wear baby-green vests. ✗ if another colour is used."},{"id":"Z10-07","a":"Z10","d":"PRD","f":"D","r":"SOP-PRO-01","b":"4.9","en":"Product dropped on the floor is discarded – never returned to the line","ar":"المنتج الساقط على الأرض يُستبعد – لا يعود للخط أبداً","c":1,"op":1,"h_ar":"راقب عمال الفحص والتعبئة واسألهم: المنتج الساقط يوضع في سلة الهالك ولا يرجع للسير. ✗ (حرج) لو منتج رجع للخط – احجز الإنتاج من آخر فحص.","h_en":"Watch and ask the inspection and packing staff: dropped product goes to the waste bin, never back on the belt. ✗ (critical) if it goes back – hold production back to the last check."},{"id":"Z10-08","a":"Z10","d":"PRD","f":"D","r":"I-C&S-01-01","b":"4.11","en":"No pressure washer (Karcher) or hose used during packing","ar":"لا استخدام للكارشر أو الخراطيم أثناء التعبئة","op":1,"h_ar":"الكارشر والخراطيم لا تستخدم في التعبئة وقت التشغيل. ✗ لو استخدمت.","h_en":"No pressure washer or hose used in packing while running. ✗ if used."},{"id":"Z10-11","a":"Z10","d":"QA","f":"D","r":"F-L&B-06-02","b":"4.9","en":"Packing-machine curtains and plastic parts intact – nothing broken or missing","ar":"ستائر وأجزاء البلاستيك بماكينات التعبئة سليمة – لا كسر أو نقص","op":1,"h_ar":"انظر داخل ماكينات التعبئة (الإشيدا): الستائر والأجزاء البلاستيكية سليمة، لا شروخ أو قطع ناقصة. ✗ لو قطعة مكسورة أو ناقصة – أبلغ الجودة فوراً.","h_en":"Look inside the packing machines (Ishida): curtains and plastic parts intact, no cracks or missing pieces. ✗ if a part is broken or missing – inform QA at once."},{"id":"Z10-12","a":"Z10","d":"MNT","f":"D","r":"F-L&B-04-01","b":"4.4","en":"No ice build-up or water dripping at the freezer entrance / exit","ar":"لا تراكم ثلج أو تنقيط مياه عند مدخل ومخرج الفريزر","op":1,"h_ar":"مدخل ومخرج الفريزر بدون ثلج متراكم ولا مياه تنقط على السيور. ✗ لو تنقيط أو ثلج كثير.","h_en":"Freezer entrance and exit free of ice build-up; no water dripping onto belts. ✗ if dripping or heavy ice."},{"id":"Z10-13","a":"Z10","d":"MNT","f":"D","r":"SGS CAR 4.3.1","b":"4.4","en":"Ceiling above sizing and packing: no flaking paint, rust or condensation","ar":"السقف أعلى التدريج والتعبئة: لا دهان متقشر أو صدأ أو تكثيف","h_ar":"انظر للسقف أعلى التدريج والتعبئة بكشاف: لا دهان متقشر أو صدأ أو تكثيف (ملاحظة SGS). ✗ لو موجود.","h_en":"Torch on the ceiling above sizing and packing: no flaking paint, rust or condensation (SGS finding). ✗ if present."},{"id":"Z10-14","a":"Z10","d":"MNT","f":"D","r":"F-QMS-12-07","b":"4.4","en":"Wall–floor joints near the freezer sealed – no exposed concrete","ar":"فواصل الحائط والأرضية قرب الفريزر محكمة – لا خرسانة مكشوفة","h_ar":"زاوية الحائط مع الأرضية قرب الفريزر محكمة ولا خرسانة مكشوفة. ✗ لو مكشوفة.","h_en":"Wall–floor joint near the freezer sealed, no exposed concrete. ✗ if exposed."},{"id":"Z10-15","a":"Z10","d":"MNT","f":"D","r":"SOP-MTN-07","b":"4.7","en":"Equipment sound: no loose or missing parts, no temporary repairs, guards fitted","ar":"المعدات سليمة: لا أجزاء مفكوكة أو مفقودة، ولا إصلاحات مؤقتة، والواقيات مركبة","h_ar":"المعدات بدون أجزاء مفكوكة أو ناقصة أو إصلاح مؤقت، والواقيات مركبة. ✗ لأي مخالفة.","h_en":"No loose or missing parts, no temporary repairs, guards fitted. ✗ for any breach."},{"id":"Z10-16","a":"Z10","d":"WH","f":"D","r":"SOP-L&B-06","b":"4.9","en":"No wooden pallets in the open-product area; plastic pallets clean and sound","ar":"لا بالتات خشبية في منطقة المنتج المكشوف، والبالتات البلاستيك نظيفة وسليمة","op":1,"h_ar":"لا بالتات خشب في منطقة المنتج المكشوف، والبالتات البلاستيك نظيفة وسليمة. ✗ لو خشب أو بالتة مكسورة.","h_en":"No wooden pallets in the open-product area; plastic pallets clean and sound. ✗ if wood or a broken pallet is there."},{"id":"Z16-06","a":"Z16","d":"QA","f":"D","r":"F-L&B-04-01","b":"4.4","en":"QC lab clean and tidy; lab fryer hood free of grease","ar":"معمل الجودة نظيف ومرتب، وهود فراير المعمل خالٍ من الدهون","h_ar":"معمل الجودة نظيف ومرتب، وهود فراير المعمل بدون دهون. ✗ لو دهون أو فوضى.","h_en":"QC lab clean and tidy; the lab fryer hood free of grease. ✗ if greasy or messy."},{"id":"Z16-09","a":"Z16","d":"QA","f":"D","r":"F-C&S-01-04","b":"3.7","en":"Yesterday's ✗ points fixed or reported to their owner","ar":"بنود ✗ أمس تم إصلاحها أو إبلاغ المسؤول عنها","h_ar":"البنود التي كانت ✗ أمس عليها علامة (كان ✗ أمس) في التطبيق وقائمتها تحت هذا البند. أثناء الجولة تأكد أن كل واحد منها تم إصلاحه أو تم إبلاغ المسؤول. ✗ لو بند ما زال كما هو بدون إبلاغ.","h_en":"Points that were ✗ yesterday are marked 'was ✗ yesterday' in the app and listed under this point. During the round check each one was fixed or reported to its owner. ✗ if one is unchanged and nobody was told.","fu":1},{"id":"Z14-01","a":"Z14","d":"WH","f":"D","r":"HACCP OPRP3","b":"4.15","en":"Final product store and stores 2–5: temperature display −18 °C or colder; doors closed","ar":"ثلاجة المنتج النهائي والثلاجات 2–5: شاشة الحرارة −18 °م أو أقل، والأبواب مغلقة","h_ar":"اقرأ شاشة الحرارة على باب كل ثلاجة: −18 °م أو أقل، والأبواب مغلقة. ✗ لو أعلى من −18 أو باب مفتوح بدون تحميل.","h_en":"Read the temperature display at each store door: −18 °C or colder, doors closed. ✗ if warmer than −18 or a door is open with no loading."},{"id":"Z14-02","a":"Z14","d":"MNT","f":"D","r":"F-L&B-04-01","b":"4.15","en":"No ice build-up on evaporators or ceiling; no dripping on stock","ar":"لا تراكم ثلج على المبخرات أو السقف، ولا تنقيط على البضاعة","h_ar":"المبخرات وسقف الثلاجات بدون ثلج كثير ولا تنقيط على البضاعة. ✗ لو تنقيط أو ثلج متراكم.","h_en":"Evaporators and cold-store ceilings without heavy ice; nothing dripping on stock. ✗ if dripping or iced up."},{"id":"Z14-03","a":"Z14","d":"WH","f":"D","r":"F-L&B-04-01","b":"4.15","en":"Cold store floors clean – no broken pallet wood or product on the floor","ar":"أرضيات الثلاجات نظيفة – لا قطع خشب بالتات أو منتج على الأرض","h_ar":"أرضية الثلاجات بدون قطع خشب من البالتات ولا منتج على الأرض. ✗ لو موجود.","h_en":"Cold-store floors free of pallet wood pieces and product. ✗ if found."},{"id":"Z14-04","a":"Z14","d":"MNT","f":"D","r":"SGS CAR 4.1.1","b":"4.4","en":"Damaged floor in the finished-product store: interim repair intact, area clean (repair by 31-01-2027)","ar":"الأرضية التالفة بثلاجة المنتج النهائي: الإصلاح المؤقت سليم والمنطقة نظيفة (الإصلاح قبل 31-01-2027)","h_ar":"الأرضية التالفة عند مدخل ثلاجة المنتج النهائي: الإصلاح المؤقت سليم والمنطقة نظيفة. ✗ لو التلف زاد.","h_en":"Damaged floor at the finished-product store entrance: interim repair intact and area clean. ✗ if the damage has grown."},{"id":"Z14-05","a":"Z14","d":"WH","f":"D","r":"SOP-L&B-06","b":"4.15","en":"Pallets sound (no broken wood); stock off walls, stable, labelled, FIFO","ar":"البالتات سليمة (لا خشب مكسور)، والبضاعة بعيدة عن الحوائط ومستقرة ومعرفة وFIFO","h_ar":"البالتات بدون خشب مكسور، البضاعة بعيدة عن الحائط، مستقرة، عليها بطاقة، والأقدم أولاً. ✗ لأي مخالفة.","h_en":"Pallets have no broken wood; stock off walls, stable, labelled, oldest first. ✗ for any breach."},{"id":"Z14-06","a":"Z14","d":"WH","f":"D","r":"SOP-PCP-01","b":"4.16","en":"Loading docks (doors 8–11) clean; dock doors closed when not loading; seals intact","ar":"أرصفة التحميل (أبواب 8–11) نظيفة، والأبواب مغلقة في غير التحميل، والجوانات سليمة","op":1,"h_ar":"أرصفة التحميل (أبواب 8–11) نظيفة، الأبواب مغلقة في غير التحميل، والجوانات سليمة. ✗ لو باب مفتوح بدون تحميل أو جوان تالف.","h_en":"Loading docks (doors 8–11) clean, doors closed when not loading, seals intact. ✗ if a door is open with no loading or a seal is damaged."},{"id":"Z14-08","a":"Z14","d":"WH","f":"D","r":"F-L&B-04-02","b":"4.15","en":"Forklifts clean with no oil leaks; charging area tidy","ar":"الكلاركات نظيفة ولا تسريب زيت، ومنطقة الشحن مرتبة","h_ar":"الكلاركات نظيفة ولا تسريب زيت، ومنطقة الشحن مرتبة. ✗ لو تسريب أو اتساخ.","h_en":"Forklifts clean with no oil leaks; charging area tidy. ✗ if leaking or dirty."},{"id":"Z14-09","a":"Z14","d":"MNT","f":"D","r":"F-L&B-04-01","b":"4.4","en":"Corridor in front of Store 1 and shipping area: floor dry, no condensation","ar":"الممر أمام ثلاجة 1 ومنطقة الشحن: الأرضية جافة، ولا تكثيف","h_ar":"الممر أمام ثلاجة 1 ومنطقة الشحن: الأرضية جافة ولا تكثيف ينقط. ✗ لو مياه أو تنقيط.","h_en":"Corridor in front of Store 1 and the shipping area: floor dry, no condensation dripping. ✗ if wet or dripping."},{"id":"Z14-10","a":"Z14","d":"QA","f":"D","r":"SOP-L&B-11","b":"3.8","en":"Held / rejected product identified with a red HOLD label and segregated","ar":"المنتج المحجوز / المرفوض معرف بملصق HOLD أحمر ومفصول","h_ar":"منطقة الحجز: كل منتج محجوز عليه ملصق HOLD أحمر ومفصول عن المنتج السليم. ✗ لو منتج محجوز بدون ملصق أو مختلط.","h_en":"Hold area: every held product carries a red HOLD label and is kept apart from good stock. ✗ if unlabelled or mixed."},{"id":"Z13-01","a":"Z13","d":"WH","f":"D","r":"F-L&B-04-01","b":"4.15","en":"Packaging and carton stores clean; materials wrapped, on pallets, 50 cm from walls","ar":"مخازن التغليف والكرتون نظيفة، والخامات مغلفة على بالتات وعلى بعد 50 سم من الحوائط","h_ar":"مخازن التغليف والكرتون نظيفة، الخامات مغلفة وعلى بالتات ومسافة 50 سم من الحائط. ✗ لأي مخالفة.","h_en":"Packaging and carton stores clean; materials wrapped, on pallets, 50 cm from walls. ✗ for any breach."},{"id":"Z13-02","a":"Z13","d":"MNT","f":"D","r":"SGS CAR 4.4.1","b":"4.4","en":"Store windows intact (acrylic boards fitted) and screens on openings","ar":"نوافذ المخازن سليمة (ألواح الأكريليك مركبة) والسلك على الفتحات","h_ar":"نوافذ المخازن: ألواح الأكريليك موجودة وغير مشروخة، والسلك على الفتحات (ملاحظة SGS). ✗ لو لوح ناقص أو مكسور.","h_en":"Store windows: acrylic boards in place and uncracked, screens on openings (SGS finding). ✗ if a board is missing or broken."},{"id":"Z13-03","a":"Z13","d":"WH","f":"D","r":"F-L&B-04-01","b":"4.15","en":"Batter ingredient stores 1 & 2 clean, labelled, FIFO; no damaged bags","ar":"مخازن مكونات البتر 1 و 2 نظيفة ومعرفة وتطبق FIFO، ولا أكياس تالفة","h_ar":"مخازن مكونات البتر 1 و 2 نظيفة، كل صنف عليه ملصق، الأقدم أولاً، ولا أكياس ممزقة. ✗ لأي مخالفة.","h_en":"Batter ingredient stores 1 & 2 clean, every item labelled, oldest first, no torn bags. ✗ for any breach."},{"id":"Z13-04","a":"Z13","d":"WH","f":"D","r":"F-L&B-04-01","b":"4.15","en":"Oil / shortening store: containers closed and labelled; no leaks or spills","ar":"مخزن الزيت / الشورتنج: العبوات مغلقة ومعرفة، ولا تسريب أو انسكاب","h_ar":"مخزن الزيت / الشورتنج: العبوات مغلقة وعليها ملصق، ولا تسريب على الأرض. ✗ لو تسريب أو عبوة مفتوحة.","h_en":"Oil / shortening store: containers closed and labelled, no leaks on the floor. ✗ if leaking or a container is open."},{"id":"Z13-06","a":"Z13","d":"MNT","f":"D","r":"SOP-L&B-12","b":"4.9","en":"Maintenance chemicals & lubricants store locked; food-grade lubricants segregated and labelled","ar":"مخزن كيماويات وزيوت الصيانة مغلق، والزيوت الغذائية مفصولة ومعرفة","h_ar":"مخزن زيوت وكيماويات الصيانة مغلق، والزيوت الغذائية في مكان منفصل وعليها ملصق. ✗ لأي مخالفة.","h_en":"Maintenance chemicals & lubricants store locked; food-grade lubricants kept apart and labelled. ✗ for any breach."},{"id":"Z13-07","a":"Z13","d":"MNT","f":"D","r":"F-L&B-04-01","b":"4.7","en":"Spare parts store tidy; small parts in closed bins","ar":"مخزن قطع الغيار مرتب، والقطع الصغيرة في صناديق مغلقة","h_ar":"مخزن قطع الغيار مرتب، والمسامير والقطع الصغيرة في صناديق مغلقة. ✗ لو قطع متناثرة.","h_en":"Spare-parts store tidy; bolts and small parts in closed bins. ✗ if parts are scattered."},{"id":"Z13-08","a":"Z13","d":"WH","f":"D","r":"F-L&B-04-01","b":"4.15","en":"No storage on the floor or against walls; aisles clear","ar":"لا تخزين على الأرض أو ملاصق للحوائط، والممرات خالية","h_ar":"لا شيء على الأرض مباشرة أو ملاصق للحائط، والممرات مفتوحة. ✗ لو مخالفة.","h_en":"Nothing directly on the floor or against walls; aisles clear. ✗ if breached."},{"id":"Z13-09","a":"Z13","d":"QA","f":"D","r":"SOP-PCP-01","b":"4.14","en":"Glue traps and bait stations in place; no pest activity","ar":"مصائد الغراء ومحطات الطعوم في أماكنها، ولا نشاط آفات","h_ar":"مصائد الغراء ومحطات الطعوم في المخازن موجودة وسليمة، ولا آفات أو آثار. ✗ لو نشاط.","h_en":"Glue traps and bait stations in the stores present and intact; no pests or signs. ✗ if there is activity."},{"id":"Z09-01","a":"Z09","d":"HYG","f":"D","r":"F-C&S-01-02","b":"4.11","en":"Dryer and equilibrium belt clean; no product stuck on belts","ar":"المجفف وسير الاتزان نظيف، ولا منتج ملتصق بالسيور","op":1,"h_ar":"انظر داخل المجفف من فتحات الفحص وعلى سير الاتزان: لا منتج ملتصق أو محروق. ✗ لو بقايا.","h_en":"Look into the dryer through the inspection doors and at the equilibrium belt: no stuck or burnt product. ✗ if residue remains."},{"id":"Z09-02","a":"Z09","d":"HYG","f":"D","r":"F-C&S-01-02","b":"4.11","en":"Batter system clean: tanks, screens, applicator and air knife – no dried batter","ar":"نظام البتر نظيف: التنكات والمصافي والمطبق وسكينة الهواء – لا بتر جاف","op":1,"h_ar":"تنكات البتر والمصافي والمطبق وسكينة الهواء بدون بتر جاف أو قشور. ✗ لو بقايا.","h_en":"Batter tanks, screens, applicator and air knife free of dried batter or crusts. ✗ if residue remains."},{"id":"Z09-03","a":"Z09","d":"HYG","f":"D","r":"F-QMS-12-06","b":"4.11","en":"Fryer exterior, oil pipes, defatting vibrator and oil miser clean – no oil build-up","ar":"السطح الخارجي للفراير ومواسير الزيت وهزاز فصل الزيت والأويل مايزر نظيفة – لا تراكم زيوت","op":1,"h_ar":"الفراير من الخارج ومواسير الزيت وهزاز فصل الزيت والأويل مايزر بدون طبقة زيت متراكمة. ✗ لو تراكم.","h_en":"Fryer exterior, oil pipes, defatting vibrator and oil miser free of oil build-up. ✗ if built up."},{"id":"Z09-04","a":"Z09","d":"HYG","f":"D","r":"F-L&B-04-01","b":"4.11","en":"Fryer hood and filters: no grease build-up or dripping","ar":"هود الفراير والفلاتر: لا تراكم أو تنقيط دهون","h_ar":"هود الفراير وفلاتره بدون دهون متراكمة أو تنقيط. ✗ لو تنقيط أو تراكم واضح.","h_en":"Fryer hood and filters: no grease build-up or dripping. ✗ if dripping or heavily built up."},{"id":"Z09-05","a":"Z09","d":"HYG","f":"D","r":"F-LAB-17-02","b":"4.11","en":"Floor: no oil or batter spills; not slippery","ar":"الأرضية: لا زيوت أو بتر منسكب، وغير زلقة","op":1,"h_ar":"امشِ حول الفراير ومطبق البتر: الأرضية بدون زيت أو بتر وليست زلقة. ✗ لو زلقة أو انسكاب.","h_en":"Walk around the fryer and batter applicator: floor free of oil or batter and not slippery. ✗ if slippery or spilled."},{"id":"Z09-06","a":"Z09","d":"HYG","f":"D","r":"F-LAB-17-02","b":"4.11","en":"Floor and under machines: no fries or product build-up","ar":"الأرضية وأسفل الماكينات: لا أصابع أو تراكم منتج","op":1,"h_ar":"الأرض وأسفل الماكينات بدون أصابع أو منتج متراكم. ✗ لو تراكم.","h_en":"Floor and under machines free of fries or product build-up. ✗ if built up."},{"id":"Z09-07","a":"Z09","d":"HYG","f":"D","r":"F-LAB-17-02","b":"4.11","en":"No standing water on the floor or on equipment frames","ar":"لا مياه راكدة على الأرضية أو على هياكل المعدات","op":1,"h_ar":"الأرضية وهياكل المعدات بدون مياه راكدة. ✗ لو بركة.","h_en":"Floor and equipment frames free of standing water. ✗ if there is a puddle."},{"id":"Z09-10","a":"Z09","d":"PRD","f":"D","r":"I-PRO-01-02","b":"4.11","en":"Dry batter bags closed and on pallets; no powder spills","ar":"أكياس البتر الجاف مغلقة وعلى بالتات، ولا انسكاب بودرة","op":1,"h_ar":"أكياس البتر الجاف بجوار الخط مغلقة وعلى بالتة، ولا بودرة على الأرض. ✗ لو مفتوحة أو انسكاب.","h_en":"Dry-batter bags at the line closed and on a pallet, no powder on the floor. ✗ if open or spilled."},{"id":"Z09-11","a":"Z09","d":"MNT","f":"D","r":"SGS CAR 4.9","b":"4.7","en":"No oil leaks from fryer, circulation pumps, pipes and valves; drip trays fitted and emptied","ar":"لا تسريب زيت من الفراير وطلمبات الدوران والمواسير والمحابس، وصواني التنقيط مركبة ومفرغة","op":1,"h_ar":"انظر أسفل الفراير وطلمبات الدوران والمواسير والمحابس: لا تسريب زيت، وصواني التنقيط موجودة وغير ممتلئة (ملاحظة SGS). ✗ لو تسريب.","h_en":"Look under the fryer, circulation pumps, pipes and valves: no oil leaks; drip trays fitted and not full (SGS finding). ✗ if leaking."},{"id":"Z09-12","a":"Z09","d":"MNT","f":"D","r":"SOP-MTN-07","b":"4.7","en":"Equipment sound: no loose or missing parts, no temporary repairs, guards fitted","ar":"المعدات سليمة: لا أجزاء مفكوكة أو مفقودة، ولا إصلاحات مؤقتة، والواقيات مركبة","h_ar":"المعدات بدون أجزاء مفكوكة أو ناقصة أو إصلاح مؤقت، والواقيات مركبة. ✗ لأي مخالفة.","h_en":"No loose or missing parts, no temporary repairs, guards fitted. ✗ for any breach."},{"id":"Z09-13","a":"Z09","d":"MNT","f":"D","r":"F-L&B-04-01","b":"4.4","en":"Overheads above dryer and fryer: no condensation, flaking paint or rust","ar":"الهياكل العلوية أعلى المجفف والفراير: لا تكثيف أو دهان متقشر أو صدأ","h_ar":"انظر أعلى المجفف والفراير بكشاف: لا تكثيف أو دهان متقشر أو صدأ. ✗ لو موجود.","h_en":"Torch above the dryer and fryer: no condensation, flaking paint or rust. ✗ if present."},{"id":"Z11-01","a":"Z11","d":"QA","f":"D","r":"SOP-L&B-12","b":"4.2","en":"Room locked when not in use; only authorised staff enter","ar":"الغرفة مغلقة عند عدم الاستخدام، والدخول للمصرح لهم فقط","h_ar":"باب غرفة البتر مغلق وقت عدم الاستخدام، ولافتة (للمصرح لهم فقط) موجودة. ✗ لو مفتوح بدون عمل.","h_en":"Batter-room door locked when not in use, \"authorised only\" sign in place. ✗ if open with nobody working."},{"id":"Z11-02","a":"Z11","d":"HYG","f":"D","r":"F-C&S-01-02","b":"4.11","en":"Mixer, scales, scoops and tools clean and stored","ar":"الخلاط والموازين والمغارف والأدوات نظيفة ومخزنة","h_ar":"الخلاط والموازين والمغارف نظيفة ومخزنة في مكانها. ✗ لو بقايا.","h_en":"Mixer, scales and scoops clean and stored in place. ✗ if residue remains."},{"id":"Z11-03","a":"Z11","d":"HYG","f":"D","r":"F-C&S-01-02","b":"4.11","en":"Floor and walls clean; no powder spills","ar":"الأرضية والحوائط نظيفة، ولا انسكاب بودرة","h_ar":"الأرضية والحوائط نظيفة ولا بودرة منسكبة. ✗ لو انسكاب.","h_en":"Floor and walls clean, no spilled powder. ✗ if spilled."},{"id":"Z11-04","a":"Z11","d":"QA","f":"D","r":"SOP-L&B-03","b":"5.3","en":"Ingredient bags closed, labelled, on pallets; allergen ingredients identified and segregated","ar":"أكياس المكونات مغلقة ومعرفة وعلى بالتات، والمكونات المسببة للحساسية معرفة ومفصولة","h_ar":"أكياس المكونات مغلقة وعليها ملصق وعلى بالتات، والمكونات المسببة للحساسية معرفة ومفصولة. ✗ لأي مخالفة.","h_en":"Ingredient bags closed, labelled, on pallets; allergen ingredients identified and kept apart. ✗ for any breach."},{"id":"Z11-05","a":"Z11","d":"HYG","f":"D","r":"F-C&S-16-02","b":"4.8","en":"Hand-wash basin and foot bath at the entrance working and stocked","ar":"حوض غسيل الأيدي وحوض الأقدام عند المدخل يعمل ومجهز","h_ar":"جرب حوض غسيل الأيدي وانظر لحوض الأقدام عند مدخل الغرفة: يعمل ومجهز. ✗ لو عطل أو فارغ.","h_en":"Try the hand-wash basin and check the foot bath at the room entrance: working and stocked. ✗ if broken or empty."},{"id":"Z08-01","a":"Z08","d":"HYG","f":"D","r":"F-C&S-01-02","b":"4.11","en":"Equipment clean after cleaning: cutters / hydro-cutters, vibrators, small-parts & sliver removers, blanchers, flumes","ar":"نظافة المعدات بعد التنظيف: ماكينات التقطيع والتقطيع المائي والهزازات وفواصل الكسر والأجزاء الجانبية والبلانشر والقنوات","op":1,"h_ar":"بعد النظافة: ماكينات التقطيع والتقطيع المائي والهزازات وفواصل الكسر والبلانشر والقنوات بدون بقايا بطاطس أو نشا. ✗ لو بقايا.","h_en":"After cleaning: cutters, hydro-cutters, vibrators, sliver and small-part removers, blanchers and flumes free of potato or starch. ✗ if residue remains."},{"id":"Z08-02","a":"Z08","d":"HYG","f":"D","r":"F-LAB-17-02","b":"4.11","en":"No starch build-up or foam on blanchers, vibrators and belts","ar":"لا تراكم نشا أو رغوة على البلانشر والهزازات والسيور","op":1,"h_ar":"البلانشر والهزازات والسيور بدون طبقة نشا بيضاء أو رغوة متراكمة. ✗ لو تراكم.","h_en":"Blanchers, vibrators and belts free of white starch layers or foam. ✗ if built up."},{"id":"Z08-03","a":"Z08","d":"HYG","f":"D","r":"F-LAB-17-02","b":"4.11","en":"Floor and under machines: no potato strips, slivers or starch","ar":"الأرضية وأسفل الماكينات: لا أصابع أو كسر أو نشا","op":1,"h_ar":"الأرض وأسفل الماكينات (استخدم كشاف): لا أصابع أو كسر أو نشا. ✗ لو تراكم.","h_en":"Floor and under machines (use a torch): no strips, slivers or starch. ✗ if built up."},{"id":"Z08-04","a":"Z08","d":"HYG","f":"D","r":"F-LAB-17-02","b":"4.11","en":"Floor: no standing water or foam; drains open and covered","ar":"الأرضية: لا مياه راكدة أو رغوة، والمجاري مفتوحة ومغطاة","op":1,"h_ar":"الأرضية بدون مياه راكدة أو رغوة، والمجاري مفتوحة ومغطاة. ✗ لو بركة أو رغوة.","h_en":"Floor free of standing water or foam; drains open and covered. ✗ if there is a puddle or foam."},{"id":"Z08-05","a":"Z08","d":"HYG","f":"D","r":"F-L&B-04-01","b":"4.11","en":"Walls and columns clean – no starch splashes","ar":"الحوائط والأعمدة نظيفة – لا رذاذ نشا","h_ar":"الحوائط والأعمدة بجوار الخط بدون رذاذ نشا أبيض. ✗ لو بقع.","h_en":"Walls and columns by the line free of white starch splashes. ✗ if stained."},{"id":"Z08-06","a":"Z08","d":"PRD","f":"D","r":"SOP-PRO-10","b":"4.11","en":"No water or foam overflow from hydro-transport, flumes and blanchers","ar":"لا فيضان مياه أو رغوة من الناقل المائي والقنوات والبلانشر","op":1,"h_ar":"لاحظ الناقل المائي والقنوات والبلانشر أثناء التشغيل: لا فيضان مياه أو رغوة على الأرض. ✗ لو فيضان.","h_en":"Watch hydro-transport, flumes and blanchers while running: no water or foam overflow onto the floor. ✗ if it overflows."},{"id":"Z08-09","a":"Z08","d":"HYG","f":"D","r":"SGS CAR III-3","b":"4.11","en":"Dosing machine and powder-additives tank exterior clean (SAPP, dextrose)","ar":"ماكينة الإضافات والسطح الخارجي لتنك الإضافات البودرة نظيف (SAPP – دكستروز)","h_ar":"السطح الخارجي لتنك الإضافات البودرة والماكينة والغطاء والأرض حولها بدون بودرة متراكمة (ملاحظة SGS). ✗ لو تراكم.","h_en":"Outside of the powder-additives tank, the dosing machine, lid and floor around: no powder build-up (SGS finding). ✗ if built up."},{"id":"Z08-10","a":"Z08","d":"HYG","f":"D","r":"I-PRO-04-01","b":"4.11","en":"Green tools and green bins used in production","ar":"استخدام الأدوات والسلات الخضراء في التصنيع","op":1,"h_ar":"أدوات وسلات التصنيع خضراء. ✗ لو لون آخر.","h_en":"Processing tools and bins are green. ✗ if another colour is used."},{"id":"Z08-12","a":"Z08","d":"MNT","f":"D","r":"SOP-MTN-07","b":"4.7","en":"Equipment sound: no loose or missing parts, no temporary repairs, guards fitted","ar":"المعدات سليمة: لا أجزاء مفكوكة أو مفقودة، ولا إصلاحات مؤقتة، والواقيات مركبة","h_ar":"المعدات بدون مسامير ناقصة أو أجزاء مفكوكة أو إصلاح بشريط/سلك، والواقيات مركبة. ✗ لأي مخالفة.","h_en":"No missing bolts, loose parts or tape/wire repairs; guards fitted. ✗ for any breach."},{"id":"Z08-13","a":"Z08","d":"MNT","f":"D","r":"F-L&B-04-01","b":"4.4","en":"Overheads above blanchers and flumes: no condensation, flaking paint or rust","ar":"الهياكل العلوية أعلى البلانشر والقنوات: لا تكثيف أو دهان متقشر أو صدأ","h_ar":"انظر أعلى البلانشر والقنوات بكشاف: لا نقاط تكثيف أو دهان متقشر أو صدأ. ✗ لو موجود.","h_en":"Torch above blanchers and flumes: no condensation, flaking paint or rust. ✗ if present."},{"id":"Z12-01","a":"Z12","d":"HYG","f":"D","r":"F-C&S-16-02","b":"4.8","en":"L2 entrance (door 12): basins, soap, sanitizer and foot bath ready","ar":"مدخل خط 2 (باب 12): الأحواض والصابون والمعقم وحوض الأقدام جاهزة","op":1,"h_ar":"مدخل خط 2 (باب 12): الأحواض نظيفة، الصابون والمعقم موجود، وحوض الأقدام ممتلئ. ✗ لأي نقص.","h_en":"L2 entrance (door 12): basins clean, soap and sanitizer present, foot bath full. ✗ for anything missing."},{"id":"Z12-02","a":"Z12","d":"PRD","f":"D","r":"SOP-L&B-03","b":"5.3","en":"L2 staff, tools, uniforms and containers stay in L2 – no crossing to L1","ar":"عمال وأدوات وزي وحاويات خط 2 تبقى في خط 2 – لا انتقال لخط 1","c":1,"op":1,"h_ar":"لاحظ عمال خط 2: لا يدخلون خط 1، وأدواتهم وحاوياتهم وزيهم لا تظهر في خط 1. ✗ (حرج) لو انتقال – خطر مسببات حساسية.","h_en":"Watch L2 staff: they do not enter L1, and their tools, containers and uniforms are not seen in L1. ✗ (critical) if they cross – allergen risk."},{"id":"Z12-03","a":"Z12","d":"WH","f":"D","r":"SOP-PRO-01","b":"5.3","en":"Allergen ingredients (wheat, milk, beans) labelled and stored separately, never above other items","ar":"المكونات المسببة للحساسية (قمح – لبن – بقوليات) معرفة ومخزنة منفصلة، وليست أعلى غيرها","h_ar":"في مخزن خط 2: القمح واللبن والبقوليات عليها ملصق مسببات الحساسية ومخزنة منفصلة، وليست فوق غيرها. ✗ لأي مخالفة.","h_en":"In the L2 store: wheat, milk and beans carry allergen labels, are stored apart and never above other items. ✗ for any breach."},{"id":"Z12-04","a":"Z12","d":"QA","f":"D","r":"SOP-L&B-03","b":"5.3","en":"After an allergen changeover: line completely free of batter and crumb residues before an allergen-free run","ar":"بعد تغيير المنتج من منتج به مسببات حساسية: الخط نظيف تماماً من بقايا البتر والبقسماط قبل تشغيل منتج خالٍ منها","c":1,"op":1,"h_ar":"إذا تغير خط 2 منذ أمس من منتج به مسببات حساسية (قمح – لبن) لمنتج خالٍ منها: افحص بكشاف الهوبر والسيور ووحدة البتر والبقسماط ومدخل القلاية – لا بقايا بتر أو بقسماط أو منتج. ✗ (حرج) لو بقايا والخط يشغل منتجاً خالياً من المسببات. لا يوجد تغيير = N/A.","h_en":"If Line 2 changed since yesterday from an allergen product (wheat, milk) to an allergen-free one: use a torch on the hopper, belts, batter and breading units and fryer entry – no batter, crumbs or product residues. ✗ (critical) if residues are found while allergen-free product runs. No changeover = N/A."},{"id":"Z12-05","a":"Z12","d":"HYG","f":"D","r":"F-C&S-01-02","b":"4.11","en":"Equipment clean: shredder, mixer, former / extruder, batter & breading, pre-fryer, oven, cooling belt, IQF, packing","ar":"نظافة المعدات: الشريدر والخلاط والفورمر / الإكسترودر والبتر والبقسماط والقلي المبدئي والفرن وسير التبريد والـ IQF والتعبئة","op":1,"h_ar":"بعد النظافة: الشريدر والخلاط والفورمر والبتر والبقسماط والقلاية والفرن وسير التبريد والـ IQF والتعبئة بدون بقايا. ✗ لو بقايا.","h_en":"After cleaning: shredder, mixer, former, batter & breading, pre-fryer, oven, cooling belt, IQF and packing free of residue. ✗ if residue remains."},{"id":"Z12-06","a":"Z12","d":"HYG","f":"D","r":"F-LAB-17-02","b":"4.11","en":"Floor and under machines: no product, batter, crumbs or potato shreds","ar":"الأرضية وأسفل الماكينات: لا منتج أو بتر أو بقسماط أو بطاطس مبشورة","op":1,"h_ar":"الأرض وأسفل الماكينات بدون منتج أو بتر أو بقسماط أو بطاطس مبشورة. ✗ لو تراكم.","h_en":"Floor and under machines free of product, batter, crumbs or potato shreds. ✗ if built up."},{"id":"Z12-07","a":"Z12","d":"HYG","f":"D","r":"F-LAB-17-02","b":"4.11","en":"Floor: no standing water or oil; drains clear","ar":"الأرضية: لا مياه راكدة أو زيوت، والمجاري مفتوحة","op":1,"h_ar":"الأرضية بدون مياه أو زيت، والمجاري مفتوحة. ✗ لو بركة أو زيت.","h_en":"Floor free of water or oil, drains open. ✗ if there is a puddle or oil."},{"id":"Z12-08","a":"Z12","d":"PRD","f":"D","r":"Hash Brown FSP","b":"4.3","en":"Cut potatoes from L1 transferred in clean, covered, identified containers","ar":"نقل البطاطس المقطعة من خط 1 في حاويات نظيفة ومغطاة ومعرفة","op":1,"h_ar":"حاويات البطاطس المقطعة القادمة من خط 1 نظيفة ومغطاة وعليها بطاقة. ✗ لو مكشوفة أو بدون بطاقة.","h_en":"Containers of cut potatoes from L1 are clean, covered and labelled. ✗ if uncovered or unlabelled."},{"id":"Z12-09","a":"Z12","d":"HYG","f":"D","r":"I-PRO-04-01","b":"5.3","en":"Allergen colour code: dedicated tools and containers for allergen products","ar":"التكويد اللوني للمسببات: أدوات وحاويات مخصصة لمنتجات المسببات","op":1,"h_ar":"أدوات وحاويات منتجات مسببات الحساسية بلونها المخصص ولا تستخدم لغيرها. ✗ لو مختلطة.","h_en":"Tools and containers for allergen products are in their dedicated colour and not used for anything else. ✗ if mixed."},{"id":"Z12-12","a":"Z12","d":"MNT","f":"D","r":"F-L&B-04-01","b":"4.4","en":"Overheads and walls: no condensation, flaking paint or rust","ar":"الهياكل العلوية والحوائط: لا تكثيف أو دهان متقشر أو صدأ","h_ar":"انظر للسقف والحوائط بكشاف: لا تكثيف أو دهان متقشر أو صدأ. ✗ لو موجود.","h_en":"Torch on ceiling and walls: no condensation, flaking paint or rust. ✗ if present."},{"id":"Z12-13","a":"Z12","d":"WH","f":"D","r":"F-L&B-04-01","b":"4.15","en":"V.A. store tidy, FIFO, no damaged bags","ar":"مخزن خط الإضافات مرتب، ويطبق FIFO، ولا أكياس تالفة","h_ar":"مخزن خط الإضافات مرتب، الأقدم يستخدم أولاً (FIFO)، ولا أكياس ممزقة. ✗ لأي مخالفة.","h_en":"V.A. store tidy, oldest used first (FIFO), no torn bags. ✗ for any breach."},{"id":"G-01","a":"G","d":"MNT","f":"D","r":"SGS CAR 4.7","b":"4.7","en":"No loose bolts, nuts, tools or parts on or above the line or on the floor","ar":"لا مسامير أو صواميل أو عدد أو قطع مفكوكة على الخط أو أعلاه أو على الأرض","c":1,"op":1,"h_ar":"امشِ بجوار كل خط وانظر على السيور والهياكل والأرض أسفلها: لا مسامير أو صواميل أو وردة أو عدة أو قطع. ✗ (حرج) لو وجدت أي قطعة – احجز المنتج من آخر فحص سليم وأبلغ الصيانة.","h_en":"Walk each line and look on belts, frames and the floor below: no bolts, nuts, washers, tools or parts. ✗ (critical) if any are found – hold product back to the last good check and call maintenance."},{"id":"G-03","a":"G","d":"MNT","f":"D","r":"SGS CAR 4.9","b":"4.7","en":"No grease, lubricant or condensation able to drip onto product or contact surfaces","ar":"لا شحوم أو زيوت تشحيم أو تكثيف يمكن أن يتساقط على المنتج أو الأسطح الملامسة","c":1,"op":1,"h_ar":"انظر أعلى الخطوط والسيور المكشوفة: لا شحم أو زيت ينقط من الرولمان أو السلاسل، ولا نقاط تكثيف تسقط على المنتج. ✗ (حرج) لو ينقط على المنتج أو سطح ملامس.","h_en":"Look above open lines and belts: no grease or oil dripping from bearings or chains, no condensation drops falling on product. ✗ (critical) if anything drips onto product or contact surfaces."},{"id":"G-05","a":"G","d":"QA","f":"D","r":"SOP-PCP-01","b":"4.14","en":"No live pests or droppings in production or storage","ar":"لا آفات حية أو فضلات في الإنتاج أو التخزين","c":1,"op":1,"h_ar":"افحص الأركان وخلف المعدات والمخازن ومصائد الغراء: لا حشرات حية أو قوارض أو فضلات. ✗ (حرج) لو نشاط – أبلغ شركة المكافحة واحجز المنتج المكشوف.","h_en":"Check corners, behind equipment, stores and glue traps: no live insects, rodents or droppings. ✗ (critical) if there is activity – call the pest contractor and hold exposed product."},{"id":"G-06","a":"G","d":"HYG","f":"D","r":"SOP-L&B-13","b":"4.9","en":"No unlabelled chemicals or spray bottles in production; chemicals kept away from product","ar":"لا كيماويات أو عبوات رش غير معرفة في الإنتاج، والكيماويات بعيدة عن المنتج","c":1,"op":1,"h_ar":"كل عبوة كيماويات أو رشاش في الصالات عليها ملصق باسم المادة، وموضوعة بعيداً عن المنتج والخامات. ✗ (حرج) لو عبوة بدون ملصق أو كيماويات بجوار المنتج.","h_en":"Every chemical container or spray bottle in the halls is labelled with its name and kept away from product and materials. ✗ (critical) if one is unlabelled or next to product."},{"id":"G-07","a":"G","d":"HYG","f":"D","r":"F-PRO-01-06","b":"4.11","en":"Cleaning tools on racks, colour-coded, clean and intact – none broken or missing","ar":"أدوات النظافة على الحوامل ومكودة لونياً ونظيفة وسليمة – لا مكسور أو مفقود","op":1,"h_ar":"افحص حوامل أدوات النظافة: الأدوات معلقة على الحامل، باللون الصحيح للمنطقة، نظيفة وسليمة، ولا أماكن فارغة على الحامل. ✗ لو أداة مكسورة أو ناقصة أو على الأرض أو لون خطأ.","h_en":"Check the cleaning-tool racks: tools hung on the rack, the right colour for the area, clean and intact, no empty places on the rack. ✗ if a tool is broken, missing, on the floor or the wrong colour."},{"id":"G-08","a":"G","d":"MNT","f":"D","r":"SOP-MTN-04","b":"4.7","en":"Food-grade lubricants only on the lines; lubrication done without contaminating product","ar":"زيوت تشحيم غذائية فقط على الخطوط، والتشحيم دون تلويث المنتج","h_ar":"انظر لعبوات الشحم والزيت المستخدمة على الخطوط واسأل الفني: مكتوب عليها Food grade (H1). ✗ لو شحم غير غذائي أو تشحيم زائد قرب المنتج.","h_en":"Look at the grease and oil used on the lines and ask the technician: labelled food grade (H1). ✗ if non-food-grade lubricant or excess grease near product."},{"id":"G-09","a":"G","d":"MNT","f":"D","r":"F-L&B-06-01","b":"4.9","en":"Light covers and plastic items above the lines intact","ar":"أغطية الإضاءة والأجزاء البلاستيكية أعلى الخطوط سليمة","h_ar":"انظر لأغطية الكشافات والبلاستيك أعلى الخطوط: موجودة وسليمة بدون شروخ. ✗ لو غطاء مكسور أو ناقص.","h_en":"Look at light covers and plastic items above the lines: present and intact, no cracks. ✗ if a cover is broken or missing."},{"id":"G-10","a":"G","d":"MNT","f":"D","r":"F-L&B-04-03","b":"4.4","en":"Lights working – no dark spots at inspection and cleaning points","ar":"الإضاءة تعمل – لا مناطق مظلمة عند نقاط الفحص والنظافة","h_ar":"انظر لطاولات الفرز ونقاط الفحص وأماكن النظافة: كل الكشافات تعمل والإضاءة كافية. ✗ لو كشاف عطلان في مكان فحص أو نظافة.","h_en":"Look at sorting tables, inspection points and cleaning areas: all lights work and light is enough. ✗ if a light is out at an inspection or cleaning point."},{"id":"Z07-01","a":"Z07","d":"HYG","f":"D","r":"F-C&S-01-02","b":"4.11","en":"Equipment clean after cleaning: dry-soil remover, de-stoner, washers, steam peeler, de-skinner, sorting table, hopper","ar":"نظافة المعدات بعد التنظيف: فاصل التراب وفاصل الأحجار والغسالات والمقشر البخاري وفاصل القشر وطاولة الفرز والهوبر","op":1,"h_ar":"افحص بالنظر وبيد عليها قفاز: فاصل التراب وفاصل الأحجار والغسالات والمقشر وفاصل القشر وطاولة الفرز والهوبر بدون طين أو قشر أو بقايا. ✗ لو بقايا على المعدات.","h_en":"Look and touch (gloved): dry-soil remover, de-stoner, washers, peeler, de-skinner, sorting table and hopper free of mud, peel or residue. ✗ if residue remains."},{"id":"Z07-02","a":"Z07","d":"HYG","f":"D","r":"F-LAB-17-02","b":"4.11","en":"No peel, soil or potato build-up on or under equipment","ar":"لا تراكم قشر أو أتربة أو بطاطس على المعدات أو أسفلها","op":1,"h_ar":"انظر على المعدات وأسفلها بكشاف: لا قشر أو طين أو بطاطس متراكمة. ✗ لو تراكم.","h_en":"Use a torch on and under the equipment: no peel, mud or potatoes built up. ✗ if there is build-up."},{"id":"Z07-03","a":"Z07","d":"HYG","f":"D","r":"F-LAB-17-02","b":"4.11","en":"Floor: no standing water; peel and water directed to drains; drains open and covered","ar":"الأرضية: لا مياه راكدة، وتوجيه القشر والمياه للمجاري، والمجاري مفتوحة ومغطاة","op":1,"h_ar":"الأرضية بدون مياه راكدة، القشر يتجه للمجاري، والمجاري مفتوحة ومغطاة بالشبكة. ✗ لو بركة أو مجرى مسدود أو بدون غطاء.","h_en":"No standing water, peel flows to drains, drains open and covered by grates. ✗ if there is a puddle, a blocked drain or a missing cover."},{"id":"Z07-04","a":"Z07","d":"HYG","f":"D","r":"F-L&B-04-01","b":"4.11","en":"Walls, columns and ceiling clean – no peel splashes or mould","ar":"الحوائط والأعمدة والسقف نظيفة – لا رذاذ قشر أو عفن","h_ar":"الحوائط والأعمدة والسقف بدون رذاذ قشر أو طين أو عفن أسود. ✗ لو بقع أو عفن.","h_en":"Walls, columns and ceiling free of peel splashes, mud or black mould. ✗ if stained or mouldy."},{"id":"Z07-05","a":"Z07","d":"PRD","f":"D","r":"SOP-PRO-10","b":"4.11","en":"No water or peel overflow from washers, peeler and flumes","ar":"لا فيضان مياه أو قشر من الغسالات والمقشر والقنوات","op":1,"h_ar":"لاحظ أثناء التشغيل: لا مياه أو قشر يفيض من الغسالات والمقشر والقنوات على الأرض. ✗ لو فيضان.","h_en":"Watch during running: no water or peel overflowing from washers, peeler or flumes onto the floor. ✗ if it overflows."},{"id":"Z07-06","a":"Z07","d":"HYG","f":"D","r":"I-PRO-04-01","b":"4.11","en":"Red tools and red bins used in peeling; cleaners in blue vests","ar":"استخدام الأدوات والسلات الحمراء في التقشير، وعمال النظافة بالسترات الزرقاء","op":1,"h_ar":"أدوات وسلات التقشير حمراء، وعمال النظافة بالسترة الزرقاء. ✗ لو لون آخر.","h_en":"Peeling tools and bins are red; cleaners wear blue vests. ✗ if another colour is used."},{"id":"Z07-07","a":"Z07","d":"MNT","f":"D","r":"SGS CAR 4.7","b":"4.7","en":"Steam peeler and steam valves: no steam leaks (condensation source)","ar":"المقشر البخاري ومحابس البخار: لا تسريب بخار (مصدر تكثيف)","h_ar":"استمع وانظر للمقشر البخاري ومحابس البخار: لا صفير أو بخار يتسرب. ✗ لو تسريب (يسبب تكثيف).","h_en":"Listen and look at the steam peeler and valves: no hissing or escaping steam. ✗ if leaking (it causes condensation)."},{"id":"Z07-08","a":"Z07","d":"MNT","f":"D","r":"SGS CAR 4.9","b":"4.4","en":"Hood above sorting conveyor and overheads: no flaking paint, rust or condensation","ar":"الهود أعلى سير الفرز والهياكل العلوية: لا دهان متقشر أو صدأ أو تكثيف","h_ar":"انظر للهود أعلى سير الفرز والسقف بكشاف: لا دهان متقشر أو صدأ أو نقاط مياه. ✗ لو تقشر أو صدأ.","h_en":"Torch on the hood above the sorting conveyor and the ceiling: no flaking paint, rust or water drops. ✗ if flaking or rusty."},{"id":"Z07-09","a":"Z07","d":"MNT","f":"D","r":"SOP-MTN-07","b":"4.7","en":"Equipment sound: no loose or missing parts, no tape / wire repairs, guards fitted","ar":"المعدات سليمة: لا أجزاء مفكوكة أو مفقودة، ولا إصلاحات بشريط أو سلك، والواقيات مركبة","h_ar":"المعدات بدون مسامير ناقصة أو أجزاء مفكوكة، ولا إصلاح بشريط لاصق أو سلك، والواقيات مركبة. ✗ لأي مخالفة.","h_en":"No missing bolts or loose parts, no tape or wire repairs, guards fitted. ✗ for any breach."},{"id":"Z07-10","a":"Z07","d":"MNT","f":"D","r":"F-QMS-12-07","b":"4.4","en":"Door between peeling and receiving closes fully – no gaps","ar":"الباب بين التقشير والاستقبال يغلق بالكامل – لا فتحات","h_ar":"أغلق الباب بين التقشير والاستقبال: يغلق بالكامل بدون فتحة. ✗ لو فتحة أو لا يغلق.","h_en":"Close the door between peeling and receiving: it shuts fully with no gap. ✗ if there is a gap or it will not close."},{"id":"Z06-01","a":"Z06","d":"WH","f":"D","r":"F-L&B-04-01","b":"4.15","en":"Raw potato stores 1–6 clean, doors closed; no rotten potatoes or bad odour","ar":"عنابر البطاطس الخام 1–6 نظيفة والأبواب مغلقة، ولا بطاطس تالفة أو روائح","h_ar":"افتح عنابر البطاطس الخام: نظيفة، الأبواب مغلقة، لا بطاطس معفنة أو رائحة. ✗ لو تعفن أو رائحة.","h_en":"Open the raw potato stores: clean, doors closed, no rotten potatoes or smell. ✗ if there is rot or odour."},{"id":"Z06-04","a":"Z06","d":"PRD","f":"D","r":"I-C&S-01-01","b":"4.11","en":"Feeding area and intake conveyor: no spilled potatoes or soil build-up","ar":"منطقة التغذية وسير الدخول: لا بطاطس متساقطة أو تراكم أتربة","op":1,"h_ar":"منطقة التغذية وسير الدخول: لا بطاطس متساقطة أو أتربة متراكمة. ✗ لو تراكم.","h_en":"Feeding area and intake conveyor: no spilled potatoes or soil build-up. ✗ if there is build-up."},{"id":"Z06-05","a":"Z06","d":"HYG","f":"D","r":"I-C&S-01-01","b":"4.11","en":"Feeding area floor: no standing water or mud; drains clear","ar":"أرضية منطقة التغذية: لا مياه راكدة أو طين، والمجاري مفتوحة","op":1,"h_ar":"أرضية منطقة التغذية: لا مياه راكدة أو طين، والمجاري مفتوحة. ✗ لو بركة أو طين.","h_en":"Feeding-area floor: no standing water or mud, drains open. ✗ if there is a puddle or mud."},{"id":"Z06-06","a":"Z06","d":"PRD","f":"D","r":"SOP-L&B-10","b":"4.12","en":"Stones, soil and small tubers collected in the designated containers","ar":"تجميع الأحجار والأتربة والدرنات الصغيرة في الحاويات المخصصة","op":1,"h_ar":"الأحجار والأتربة والدرنات الصغيرة في الحاويات المخصصة وليست على الأرض. ✗ لو على الأرض.","h_en":"Stones, soil and small tubers go into the designated containers, not on the floor. ✗ if they are on the floor."},{"id":"Z06-07","a":"Z06","d":"QA","f":"D","r":"F-L&B-04-01","b":"4.4","en":"Raw receiving lab clean and tidy","ar":"معمل استلام الخام نظيف ومرتب","h_ar":"معمل استلام الخام عند البوابة نظيف ومرتب. ✗ لو متسخ.","h_en":"The raw receiving lab at the gate is clean and tidy. ✗ if dirty."},{"id":"Z06-08","a":"Z06","d":"WH","f":"D","r":"SOP-PCP-01","b":"4.14","en":"Receiving doors closed when not unloading; pest devices intact","ar":"أبواب الاستلام مغلقة في غير أوقات التفريغ، وأجهزة المكافحة سليمة","h_ar":"أبواب الاستلام مغلقة وقت عدم التفريغ، وأجهزة المكافحة بجوارها سليمة. ✗ لو باب مفتوح بدون تفريغ أو جهاز ناقص.","h_en":"Receiving doors closed when not unloading; pest devices next to them intact. ✗ if a door is open with no unloading or a device is missing."},{"id":"Z15-01","a":"Z15","d":"MNT","f":"D","r":"F-L&B-04-01","b":"4.5","en":"Boiler area (steam & thermal oil): floor dry, no leaks, tidy","ar":"منطقة الغلايات (البخار والزيت الحراري): الأرضية جافة، ولا تسريبات، ومرتبة","h_ar":"منطقة الغلايات: الأرضية جافة، لا تسريب مياه أو زيت حراري، والمكان مرتب. ✗ لو مياه أو تسريب.","h_en":"Boiler area: floor dry, no water or thermal-oil leaks, tidy. ✗ if wet or leaking."},{"id":"Z15-02","a":"Z15","d":"MNT","f":"D","r":"SGS CAR 4.7","b":"4.5","en":"Steam lines and valves in production: no leaks","ar":"خطوط ومحابس البخار في الإنتاج: لا تسريب","h_ar":"امشِ بجوار خطوط البخار في الإنتاج: لا صفير أو بخار يتسرب من المحابس. ✗ لو تسريب (يسبب تكثيف).","h_en":"Walk along steam lines in production: no hissing or steam escaping from valves. ✗ if leaking (it causes condensation)."},{"id":"Z15-04","a":"Z15","d":"MNT","f":"D","r":"F-L&B-04-01","b":"4.5","en":"Ammonia / refrigeration plant: no leaks; area clean","ar":"محطة الأمونيا / التبريد: لا تسريبات، والمنطقة نظيفة","h_ar":"محطة الأمونيا والتبريد: لا رائحة أمونيا أو تسريب، والمكان نظيف. ✗ لو رائحة أو تسريب – أبلغ فوراً.","h_en":"Ammonia / refrigeration plant: no ammonia smell or leak, area clean. ✗ if there is a smell or leak – report immediately."},{"id":"Z15-05","a":"Z15","d":"MNT","f":"D","r":"F-MTN-02-01","b":"4.5","en":"Ventilation and air-intake filters clean and not clogged","ar":"فلاتر التهوية ومداخل الهواء نظيفة وغير مسدودة","h_ar":"انظر لفلاتر التهوية ومداخل الهواء: لا تراب متراكم أو انسداد أو فلتر ناقص. ✗ لو متسخة أو مسدودة.","h_en":"Look at the ventilation filters and air intakes: no dust build-up, no blockage, no missing filter. ✗ if dirty or blocked."},{"id":"Z15-06","a":"Z15","d":"HYG","f":"D","r":"F-L&B-04-01","b":"4.4","en":"MCC and electric rooms and their stairs clean; doors closed","ar":"غرف MCC والكهرباء وسلالمها نظيفة، والأبواب مغلقة","h_ar":"غرف MCC والكهرباء وسلالمها نظيفة بدون أتربة، والأبواب مغلقة. ✗ لو أتربة متراكمة.","h_en":"MCC and electric rooms and their stairs free of dust; doors closed. ✗ if dusty."},{"id":"Z15-07","a":"Z15","d":"MNT","f":"D","r":"F-L&B-04-01","b":"4.7","en":"Maintenance workshop tidy; swarf and metal shavings contained","ar":"ورشة الصيانة مرتبة، وبرادة المعادن محصورة","h_ar":"ورشة الصيانة مرتبة، والبرادة والقطع المعدنية في صندوق ولا تخرج على أحذية العمال للإنتاج. ✗ لو فوضى أو برادة منتشرة.","h_en":"Workshop tidy; swarf and metal pieces in a container, not carried into production on shoes. ✗ if messy or swarf is spread."},{"id":"Z15-09","a":"Z15","d":"QA","f":"D","r":"F-L&B-07-01","b":"4.5","en":"Water tank closed and clean; softener working","ar":"خزان المياه مغلق ونظيف، والسوفتنر يعمل","h_ar":"غطاء خزان المياه مغلق، ولا أوساخ أو مياه راكدة حوله، والسوفتنر يعمل بدون إنذار. ✗ لو الغطاء مفتوح أو المكان متسخ.","h_en":"Water-tank lid closed, no dirt or standing water around it, softener running with no alarm. ✗ if the lid is open or the area is dirty."},{"id":"Z15-10","a":"Z15","d":"ADM","f":"D","r":"SOP-PCP-01","b":"4.14","en":"Idle areas (vegetable hall, unused rooms) closed, clean, no junk, no pests","ar":"المناطق غير المستخدمة (صالة الخضار – الغرف غير المستخدمة) مغلقة ونظيفة ولا كراكيب ولا آفات","h_ar":"صالة الخضار والغرف غير المستخدمة مغلقة ونظيفة، لا كراكيب ولا آفات. ✗ لأي مخالفة.","h_en":"Vegetable hall and unused rooms closed, clean, no junk, no pests. ✗ for any breach."},{"id":"Z15-11","a":"Z15","d":"MNT","f":"D","r":"SOP-PCP-01","b":"4.14","en":"Unused equipment inside: clean, off the floor, away from walls","ar":"المعدات غير المستخدمة بالداخل نظيفة ومرفوعة عن الأرض وبعيدة عن الحوائط","h_ar":"المعدات غير المستخدمة نظيفة ومرفوعة عن الأرض وبعيدة عن الحائط. ✗ لو على الأرض أو متسخة.","h_en":"Unused equipment clean, off the floor and away from walls. ✗ if on the floor or dirty."},{"id":"Z02-01","a":"Z02","d":"ADM","f":"D","r":"F-QMS-12-07","b":"4.12","en":"External waste containers closed with lids, not overflowing or leaking","ar":"حاويات النفايات الخارجية مغلقة بغطاء وغير ممتلئة ولا تسرب","h_ar":"حاويات النفايات الخارجية: مغلقة بالغطاء، غير ممتلئة لآخرها، ولا سوائل تتسرب. ✗ لو حاوية مفتوحة أو بها تسرب.","h_en":"External waste containers: lids closed, not full to the top, no liquid leaking. ✗ if a container is open or leaking."},{"id":"Z02-02","a":"Z02","d":"ADM","f":"D","r":"SOP-L&B-10","b":"4.12","en":"Waste segregated and identified (peel/potato, cartons, plastic, oil, general)","ar":"النفايات مفصولة ومعرفة (قشر/بطاطس – كرتون – بلاستيك – زيت – عامة)","h_ar":"كل نوع نفايات في مكانه (قشر/بطاطس – كرتون – بلاستيك – زيت – عامة) ومعرف بلافتة. ✗ لو نفايات مخلوطة.","h_en":"Each waste type is in its place (peel/potato, cartons, plastic, oil, general) with a sign. ✗ if waste is mixed."},{"id":"Z02-03","a":"Z02","d":"ADM","f":"D","r":"SOP-L&B-10","b":"4.12","en":"Waste removed regularly – no build-up; area organised","ar":"رفع النفايات بانتظام – لا تراكم، والمنطقة منظمة","h_ar":"لا نفايات متراكمة من أيام سابقة والمنطقة مرتبة. اسأل عن آخر رفع. ✗ لو تراكم أو فوضى.","h_en":"No waste left from previous days; area tidy. Ask when it was last collected. ✗ if there is build-up or mess."},{"id":"Z02-04","a":"Z02","d":"ADM","f":"D","r":"SOP-L&B-10","b":"4.12","en":"Waste area floor clean and drained; no leachate or bad odour","ar":"أرضية منطقة النفايات نظيفة ومصرفة، ولا سوائل متسربة أو روائح كريهة","h_ar":"أرضية منطقة النفايات نظيفة وجافة أو مصرفة، ولا روائح قوية. ✗ لو سوائل متجمعة أو رائحة كريهة.","h_en":"Waste-area floor clean and dry or drained, no strong smell. ✗ if liquid pools or it smells bad."},{"id":"Z02-05","a":"Z02","d":"QA","f":"D","r":"SOP-PCP-01","b":"4.14","en":"No flies, birds or rodent activity around the waste area","ar":"لا ذباب أو طيور أو نشاط قوارض حول منطقة النفايات","h_ar":"قف دقيقتين عند منطقة النفايات: لا ذباب كثير أو طيور أو آثار قوارض. ✗ لو نشاط واضح.","h_en":"Stand at the waste area for 2 minutes: no swarms of flies, birds or rodent signs. ✗ if activity is obvious."},{"id":"Z02-06","a":"Z02","d":"PRD","f":"D","r":"SOP-L&B-10","b":"4.12","en":"Used frying oil in closed, labelled containers; no spills","ar":"زيت القلي المستعمل في عبوات مغلقة ومعرفة، ولا انسكابات","h_ar":"براميل الزيت المستعمل مغلقة وعليها ملصق، ولا زيت منسكب حولها. ✗ لو مفتوحة أو انسكاب.","h_en":"Used-oil drums are closed and labelled, no oil spilled around them. ✗ if open or spilled."},{"id":"Z02-07","a":"Z02","d":"PRD","f":"D","r":"SOP-L&B-12","b":"4.3","en":"Waste leaves production only through the waste door / route; waste door closed","ar":"خروج النفايات من الإنتاج عبر باب/مسار النفايات فقط، وباب النفايات مغلق","op":1,"h_ar":"الهالك يخرج من باب النفايات فقط وليس من باب المنتج، وباب النفايات مغلق بعد الاستخدام. ✗ لو نفايات تمر من مسار المنتج أو الباب مفتوح.","h_en":"Waste leaves only through the waste door, never the product door, and the waste door is closed after use. ✗ if waste uses the product route or the door stays open."},{"id":"Z02-08","a":"Z02","d":"WH","f":"D","r":"F-L&B-04-01","b":"4.12","en":"No carton or packaging waste piled inside buildings (pest harbourage)","ar":"لا تراكم لمخلفات الكرتون والتغليف داخل المباني (مأوى للآفات)","h_ar":"امشِ في المخازن والممرات: لا كرتون أو تغليف مستعمل متراكم. ✗ لو تراكم.","h_en":"Walk the stores and corridors: no used cartons or packaging piled up. ✗ if there is build-up."},{"id":"Z01-01","a":"Z01","d":"ADM","f":"D","r":"F-L&B-04-01","b":"4.1","en":"Roads, yards & perimeter clean: no litter, potatoes, cartons or loose pallets","ar":"الطرق والساحات والمحيط نظيفة: لا مخلفات أو بطاطس أو كرتون أو بالتات متروكة","h_ar":"امشِ حول المصنع (الطرق والساحات والسور): لا مخلفات أو بطاطس أو كرتون أو بالتات متروكة. ✗ لو وجدت تراكم.","h_en":"Walk around the site (roads, yards, fence): no litter, potatoes, cartons or loose pallets. ✗ if there is build-up."},{"id":"Z01-02","a":"Z01","d":"ADM","f":"D","r":"F-L&B-04-01","b":"4.1","en":"No weeds or vegetation along walls, docks and pipes","ar":"لا حشائش أو نباتات بجوار الحوائط والأرصفة والمواسير","h_ar":"انظر بجوار الحوائط الخارجية والأرصفة والمواسير: لا حشائش أو نباتات. ✗ لو وجدت حشائش.","h_en":"Look along external walls, docks and pipes: no weeds or plants. ✗ if weeds are found."},{"id":"Z01-03","a":"Z01","d":"ADM","f":"D","r":"F-L&B-04-01","b":"4.1","en":"No standing water on roads & yards; water drains away from buildings","ar":"لا مياه راكدة على الطرق والساحات، وتصريف المياه بعيداً عن المباني","h_ar":"انظر للطرق والساحات حول المباني: لا مياه راكدة، والمياه تذهب للمصارف بعيداً عن المباني. ✗ لو بركة مياه.","h_en":"Look at roads and yards around the buildings: no standing water; water runs to drains away from buildings. ✗ if there is a puddle."},{"id":"Z01-04","a":"Z01","d":"MNT","f":"D","r":"F-L&B-04-01","b":"4.4","en":"External walls, roof edges & cladding intact – no holes, cracks or gaps for pests","ar":"الحوائط الخارجية وحواف السقف سليمة – لا ثقوب أو شقوق أو فتحات لدخول الآفات","h_ar":"انظر للحوائط الخارجية وحواف السقف وحول المواسير والكابلات: لا ثقوب أو شقوق أو فتحات. ✗ لو فتحة يمكن أن تدخل منها آفات.","h_en":"Look at external walls, roof edges and around pipes and cables: no holes, cracks or gaps. ✗ if pests could get in."},{"id":"Z01-05","a":"Z01","d":"MNT","f":"D","r":"SOP-PCP-01","b":"4.14","en":"External doors, emergency exits & windows closed; seals intact, no gaps under doors","ar":"الأبواب الخارجية ومخارج الطوارئ والنوافذ مغلقة، والجوانات سليمة ولا فتحات أسفل الأبواب","h_ar":"افحص الأبواب الخارجية ومخارج الطوارئ والنوافذ: مغلقة، الجوانات سليمة، ولا ضوء يظهر أسفل الباب. ✗ لو باب مفتوح بدون سبب أو فتحة أسفله.","h_en":"Check external doors, emergency exits and windows: closed, seals intact, no daylight under doors. ✗ if open for no reason or there is a gap."},{"id":"Z01-06","a":"Z01","d":"QA","f":"D","r":"SOP-PCP-01","b":"4.14","en":"External bait stations in place, numbered, intact and accessible (site pest map)","ar":"محطات الطعوم الخارجية في أماكنها ومرقمة وسليمة ويمكن الوصول إليها (خريطة المكافحة)","h_ar":"امشِ حول المبنى وافحص 5 محطات طعوم خارجية على الأقل: موجودة، عليها رقم، مثبتة وغير مكسورة، ولا شيء يمنع الوصول لها. ✗ لو محطة ناقصة أو مكسورة أو بدون رقم.","h_en":"Walk around the building and check at least 5 external bait stations: present, numbered, fixed, unbroken and nothing blocking them. ✗ if one is missing, broken or unnumbered."},{"id":"Z01-07","a":"Z01","d":"ADM","f":"D","r":"SOP-L&B-02","b":"4.2","en":"Gate manned; no visitor, driver or contractor enters without the guard's permission","ar":"البوابة بها فرد أمن، ولا دخول للزوار أو السائقين أو المقاولين بدون إذن الأمن","h_ar":"عند البوابة: يوجد فرد أمن، والبوابة ليست مفتوحة بدون رقابة، والأمن يوقف الزوار والسائقين قبل الدخول. ✗ لو البوابة بدون أمن أو مفتوحة بدون رقابة.","h_en":"At the gate: a guard is present, the gate is not left open unattended, and the guard stops visitors and drivers before they enter. ✗ if the gate is unmanned or open without control."},{"id":"Z01-08","a":"Z01","d":"ADM","f":"D","r":"I-C&S-01-01","b":"4.1","en":"Truck scale (weighbridge) & room clean – no spilled potatoes or soil","ar":"الباسكول وغرفته نظيفة – لا بطاطس أو أتربة متساقطة","h_ar":"انظر للباسكول وغرفته: نظيفة، لا بطاطس أو طين متراكم. ✗ لو تراكم.","h_en":"Look at the weighbridge and its room: clean, no potatoes or mud built up. ✗ if there is build-up."},{"id":"Z01-09","a":"Z01","d":"MNT","f":"D","r":"SOP-PCP-01","b":"4.14","en":"Equipment & materials stored outside: raised, tidy, away from walls, no pest harbourage","ar":"المعدات والمواد المخزنة بالخارج مرفوعة ومرتبة وبعيدة عن الحوائط ولا تأوي آفات","h_ar":"المعدات والخامات المخزنة بالخارج: مرفوعة عن الأرض، مرتبة، بعيدة عن الحائط، ولا حشائش أو مخلفات حولها. ✗ لو مكدسة على الأرض أو ملاصقة للحائط.","h_en":"Equipment and materials stored outside: raised, tidy, away from walls, no weeds or waste around. ✗ if piled on the ground or against walls."},{"id":"Z01-10","a":"Z01","d":"ADM","f":"D","r":"SOP-PRO-01","b":"4.8","en":"Smoking only in the designated area; area clean with an ash bin","ar":"التدخين في المكان المخصص فقط، والمكان نظيف وبه طفاية","h_ar":"مكان التدخين المخصص نظيف وبه طفاية، ولا أعقاب سجائر في أماكن أخرى. ✗ لو تدخين خارج المكان أو المكان متسخ.","h_en":"The smoking area is clean with an ash bin, and there are no cigarette ends elsewhere. ✗ if smoking happens elsewhere or the area is dirty."},{"id":"Z05-01","a":"Z05","d":"ADM","f":"D","r":"I-C&S-01-01","b":"4.8","en":"Cafeteria tables, chairs and floor clean after each meal break","ar":"طاولات وكراسي وأرضية الكافتيريا نظيفة بعد كل استراحة","op":1,"h_ar":"الكافتيريا بعد آخر استراحة: الطاولات والكراسي والأرضية نظيفة. ✗ لو بقايا طعام.","h_en":"Cafeteria after the last break: tables, chairs and floor clean. ✗ if food is left."},{"id":"Z05-02","a":"Z05","d":"ADM","f":"D","r":"I-C&S-01-01","b":"4.8","en":"Kitchen and food store clean; food covered, refrigerated and in date","ar":"المطبخ ومخزن الطعام نظيف، والطعام مغطى ومبرد وصالح","h_ar":"المطبخ ومخزن الطعام نظيف، الطعام مغطى، الثلاجة باردة، ولا طعام منتهي الصلاحية. ✗ لأي مخالفة.","h_en":"Kitchen and food store clean, food covered, fridge cold, nothing out of date. ✗ for any breach."},{"id":"Z05-03","a":"Z05","d":"ADM","f":"D","r":"SOP-PCP-01","b":"4.12","en":"Food waste removed; bins lidded","ar":"رفع بقايا الطعام، والسلات بغطاء","op":1,"h_ar":"بقايا الطعام مرفوعة والسلات مغطاة. ✗ لو سلة مفتوحة أو بقايا متراكمة.","h_en":"Food waste removed and bins covered. ✗ if a bin is open or waste is piling up."},{"id":"Z05-04","a":"Z05","d":"ADM","f":"D","r":"F-L&B-04-01","b":"4.8","en":"Drinking-water coolers clean and working; cups available","ar":"كولدير مياه الشرب نظيف ويعمل، والأكواب متوفرة","h_ar":"كولدير مياه الشرب نظيف ويعمل ومياهه باردة، والأكواب متوفرة. ✗ لو متسخ أو عطلان أو بدون أكواب.","h_en":"Drinking-water cooler clean, working and cold; cups available. ✗ if dirty, broken or no cups."},{"id":"Z05-05","a":"Z05","d":"ADM","f":"D","r":"SOP-PRO-01","b":"7.4","en":"Laundry: clean and dirty uniforms kept separate; no pile of dirty uniforms","ar":"المغسلة: الزي النظيف منفصل عن المتسخ، ولا زي متسخ متراكم","h_ar":"في المغسلة: الزي النظيف في مكان والمتسخ في مكان آخر، ولا كومة زي متسخ متراكمة من أيام سابقة. ✗ لو مختلط أو متراكم.","h_en":"In the laundry: clean uniforms in one place and dirty ones in another; no pile of dirty uniforms left from earlier days. ✗ if mixed or piled up."},{"id":"Z05-06","a":"Z05","d":"ADM","f":"D","r":"I-C&S-01-01","b":"4.1","en":"Mosque and ablution area clean; no water leaks","ar":"المسجد ومكان الوضوء نظيف، ولا تسريب مياه","h_ar":"المسجد ومكان الوضوء نظيف، ولا تسريب مياه. ✗ لو متسخ أو تسريب.","h_en":"Mosque and ablution area clean, no water leaks. ✗ if dirty or leaking."},{"id":"Z05-07","a":"Z05","d":"QA","f":"D","r":"SOP-PCP-01","b":"4.14","en":"Insect light traps working; no flies or cockroaches","ar":"صواعق الحشرات تعمل، ولا ذباب أو صراصير","h_ar":"صواعق الحشرات في الكافتيريا تعمل، ولا ذباب أو صراصير. ✗ لو صاعق عطلان أو آفات.","h_en":"Insect killers in the cafeteria work; no flies or cockroaches. ✗ if a unit is off or pests are seen."},{"id":"Z05-08","a":"Z05","d":"ADM","f":"D","r":"I-C&S-01-01","b":"4.1","en":"Admin building offices and pantry clean","ar":"مكاتب ومطبخ المبنى الإداري نظيفة","h_ar":"نظرة سريعة على مكاتب ومطبخ المبنى الإداري: نظيفة ومرتبة. ✗ لو متسخة.","h_en":"Quick look at admin offices and pantry: clean and tidy. ✗ if dirty."},{"id":"Z04-02","a":"Z04","d":"HYG","f":"D","r":"F-C&S-16-02","b":"4.8","en":"Floors, toilets and urinals clean; flushing works","ar":"الأرضيات والمراحيض والمباول نظيفة والسيفون يعمل","op":1,"h_ar":"ادخل كل دورة مياه: الأرضية والمراحيض والمباول نظيفة، وجرب السيفون. ✗ لو متسخة أو السيفون لا يعمل.","h_en":"Enter every toilet: floor, toilets and urinals clean; test the flush. ✗ if dirty or the flush does not work."},{"id":"Z04-03","a":"Z04","d":"HYG","f":"D","r":"F-C&S-16-02","b":"4.8","en":"Liquid soap, sanitizer, paper towels / dryer and toilet paper available","ar":"الصابون السائل والمعقم والمناديل / المجفف وورق التواليت متوفرة","op":1,"h_ar":"في كل دورة مياه: صابون ومعقم ومناديل أو مجفف وورق تواليت. ✗ لو صنف خلص.","h_en":"In every toilet: soap, sanitizer, towels or dryer and toilet paper. ✗ if anything has run out."},{"id":"Z04-04","a":"Z04","d":"HYG","f":"D","r":"F-C&S-16-02","b":"4.8","en":"Bins lidded and emptied; drains clear; no bad odour","ar":"السلات بغطاء ومفرغة، والمجاري مفتوحة، ولا روائح كريهة","op":1,"h_ar":"السلات بغطاء وغير ممتلئة، والمجاري مفتوحة، ولا رائحة كريهة. ✗ لو سلة ممتلئة أو مجرى مسدود أو رائحة.","h_en":"Bins lidded and not full, drains open, no bad smell. ✗ if a bin is full, a drain blocked or it smells."},{"id":"Z04-05","a":"Z04","d":"HYG","f":"D","r":"I-PRO-04-01","b":"4.11","en":"Yellow tools used only in toilets and stored in place","ar":"الأدوات الصفراء تستخدم في دورات المياه فقط ومخزنة في مكانها","op":1,"h_ar":"أدوات تنظيف دورات المياه صفراء ومخزنة في مكانها، ولا تستخدم في أي مكان آخر. ✗ لو لون آخر أو الأدوات الصفراء خارج دورات المياه.","h_en":"Toilet cleaning tools are yellow, stored in place and not used anywhere else. ✗ if another colour is used or yellow tools are outside the toilets."},{"id":"Z04-06","a":"Z04","d":"MNT","f":"D","r":"F-L&B-04-02","b":"4.8","en":"Fixtures sound: no leaking taps or flush, exhaust fans working, doors self-closing","ar":"التجهيزات سليمة: لا تسريب من الصنابير أو السيفون، والشفاطات تعمل، والأبواب ذاتية الغلق","h_ar":"جرب الصنابير والسيفون (لا تسريب)، والشفاطات تعمل، والأبواب تغلق وحدها. ✗ لو أي عطل.","h_en":"Test taps and flush (no leaks), fans work, doors self-close. ✗ for any fault."},{"id":"Z04-07","a":"Z04","d":"HYG","f":"D","r":"F-C&S-16-02","b":"4.8","en":"\"Wash your hands\" sign posted; toilets do not open directly onto food areas","ar":"لافتة \"اغسل يديك\" موجودة، ودورات المياه لا تفتح مباشرة على مناطق الغذاء","h_ar":"لافتة (اغسل يديك) موجودة، ودورة المياه تفتح على ممر وليس مباشرة على صالة إنتاج. ✗ لو اللافتة غير موجودة.","h_en":"\"Wash your hands\" sign in place; the toilet opens to a corridor, not straight into a food hall. ✗ if the sign is missing."}]};
